import asyncio
import base64
from pathlib import Path

from backend.app.celery_tasks.celery_init import app
from backend.app.celery_tasks.pdf_tasks.utils import generate_html
from backend.app.core.db import engine, create_session_pool
from backend.app.crud.invoice import get_invoice_with_client


async def invoice_task(invoice_id):
    try:
        async with create_session_pool(engine)() as session:
            invoice = await get_invoice_with_client(session=session, invoice_id=invoice_id)
            TEMPLATE_DIR = Path(__file__).parent
            return generate_html(invoice, Path(TEMPLATE_DIR, 'invoice_template.html'))
    finally:
        await engine.dispose()



@app.task(bind=True, name='render_pdf', max_retries=3, default_retry_delay=5)
def render_pdf(self, invoice_id):
    from weasyprint import HTML
    async def _run():
        return await invoice_task(invoice_id)

    html_content = asyncio.run(_run())

    pdf_bytes = HTML(string=html_content).write_pdf()
    base64_pdf = base64.b64encode(pdf_bytes).decode('utf-8')

    return base64_pdf


